mapper.select:
select uwc.id, uwc.user_id as userId, uwc.ai_service_id as aiServiceId, uwc.ai_service_key as aiServiceKey, uwc.model_id as modelId, uwc.search_service_id as searchServiceId, uwc.search_service_key as searchServiceKey,
su.user_name as userName, ase.service_name as serviceName,ss.service_name as searchServiceName,am.model_name as ModelName
from user_webui_config uwc
left join ai_service ase on ase.id = uwc.ai_service_id
left join ai_model am on am.id=uwc.model_id
left join search_service ss on uwc.search_service_id = ss.id
left join sys_user su on su.user_id=uwc.user_id

     and uwc.user_id = #{userId}
     and uwc.ai_service_id = #{aiServiceId}
     and uwc.ai_service_key = #{aiServiceKey}
     and uwc.model_id = #{modelId}
     and uwc.search_service_id = #{searchServiceId}
     and uwc.search_service_key = #{searchServiceKey}

mapper.update:
update user_webui_config
user_id = #{userId}, ai_service_id = #{aiServiceId}, ai_service_key = #{aiServiceKey}, model_id = #{modelId}, search_service_id = #{searchServiceId}, search_service_key = #{searchServiceKey},
where id = #{id}
